import React, { createContext, useContext, useState, useEffect } from 'react';
import useOfflineSync from '../hooks/useOfflineSync';

const OfflineContext = createContext();

export const OfflineProvider = ({ children }) => {
    // Get offline sync capabilities
    const offlineSync = useOfflineSync();

    // Additional state for pending uploads (legacy support)
    const [isOffline, setIsOffline] = useState(!navigator.onLine);
    const [pendingUploads, setPendingUploads] = useState([]);

    // Monitor online/offline status
    useEffect(() => {
        const handleOnline = () => setIsOffline(false);
        const handleOffline = () => setIsOffline(true);

        window.addEventListener('online', handleOnline);
        window.addEventListener('offline', handleOffline);

        return () => {
            window.removeEventListener('online', handleOnline);
            window.removeEventListener('offline', handleOffline);
        };
    }, []);

    // Queue media for upload when offline
    const queueMediaUpload = (donorId, media) => {
        setPendingUploads(prev => [
            ...prev,
            { donorId, media, timestamp: Date.now() }
        ]);
    };

    // Process pending uploads when back online
    useEffect(() => {
        if (isOffline || pendingUploads.length === 0) return;

        const processUploads = async () => {
            // In a real app, this would make API calls to upload media
            console.log('Processing pending uploads:', pendingUploads);

            // Mock successful upload with delay
            await new Promise(resolve => setTimeout(resolve, 1000));

            // Clear processed uploads
            setPendingUploads([]);
        };

        processUploads();
    }, [isOffline, pendingUploads]);

    // Combine both approaches for backwards compatibility
    return (
        <OfflineContext.Provider value={{
            ...offlineSync,
            queueMediaUpload,
            pendingUploads
        }}>
            {children}
        </OfflineContext.Provider>
    );
};

export const useOffline = () => useContext(OfflineContext);
